import { WILAYAS, communesOf } from "/js/algeria-data.js";

const app = document.querySelector("#app");
const money = new Intl.NumberFormat("fr-DZ", { maximumFractionDigits: 0 });
const icon = (name) => ({
  bag: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 8h12l1 12H5L6 8Zm3 0a3 3 0 0 1 6 0"/></svg>',
  arrow: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>',
  close: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  minus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14"/></svg>',
  truck: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h11v11H3zM14 9h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>',
  sliders: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 17h16M8 3v8M16 13v8"/></svg>',
  image: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m21 15-5-5L5 20"/></svg>',
  chart: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19V5M4 19h16M8 16v-4M12 16V7M16 16v-7"/></svg>',
  database: '<svg viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="12" cy="5" rx="7" ry="3"/><path d="M5 5v7c0 1.7 3.1 3 7 3s7-1.3 7-3V5M5 12v7c0 1.7 3.1 3 7 3s7-1.3 7-3v-7"/></svg>',
  logout: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 17l5-5-5-5M15 12H3M14 4h5v16h-5"/></svg>',
  search: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>',
  eye: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg>',
  shield: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 20 6v5c0 5-3.3 8.4-8 10-4.7-1.6-8-5-8-10V6l8-3Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/></svg>',
  menu: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg>',
}[name] || "");

const copy = {
  en: {
    shop: "Shop", collections: "Collections", projects: "Projects", contact: "Contact", room: "The KDB room", bag: "Bag", discover: "Discover the edit",
    all: "All pieces", search: "Search material, colour, or collection", add: "Add to bag", details: "View study", cod: "Cash on delivery", checkout: "Place COD order",
    fullName: "Full name", phone: "Phone number", wilaya: "Wilaya", delivery: "Delivery", stopDesk: "Pickup point / Stop Desk", domicile: "Domicile delivery", baladiya: "Baladiya",
    contactTitle: "Start with the room.", contactBody: "For material questions, project notes, or delivery help, speak with the KDB studio.", language: "العربية",
  },
  ar: {
    shop: "المتجر", collections: "المجموعات", projects: "المشاريع", contact: "تواصل", room: "غرفة KDB", bag: "السلة", discover: "اكتشف المجموعة",
    all: "كل القطع", search: "ابحث عن مادة أو لون أو مجموعة", add: "أضف إلى السلة", details: "عرض القطعة", cod: "الدفع عند الاستلام", checkout: "تأكيد طلب الدفع عند الاستلام",
    fullName: "الاسم الكامل", phone: "رقم الهاتف", wilaya: "الولاية", delivery: "التوصيل", stopDesk: "نقطة الاستلام / Stop Desk", domicile: "التوصيل إلى المنزل", baladiya: "البلدية",
    contactTitle: "ابدأ من الغرفة.", contactBody: "للاستفسار عن المواد أو المشاريع أو التوصيل، تواصل مع استوديو KDB.", language: "English",
  },
};

const safe = (value) => String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#039;", '"': "&quot;" }[char]));
const format = (value) => `${money.format(Number(value || 0))} DA`;
const label = (key) => copy[state.lang][key] || key;
const localized = (record, field = "name") => state.lang === "ar" && record?.[`${field}Ar`] ? record[`${field}Ar`] : record?.[field] || "";
const jsonText = (value) => safe(JSON.stringify(value ?? [], null, 2));
const parseJson = (value, title) => {
  try { return JSON.parse(value || "[]"); } catch { throw new Error(`${title} must be valid JSON.`); }
};
const api = async (url, options = {}) => {
  const response = await fetch(url, { headers: { "content-type": "application/json", ...(options.headers || {}) }, ...options });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || "Request could not be completed.");
  return data;
};

const savedCart = JSON.parse(localStorage.getItem("kdb-hb-cart") || "[]");
const state = {
  store: null, cart: Array.isArray(savedCart) ? savedCart : [], bagOpen: false, order: null, productId: null,
  lang: localStorage.getItem("kdb-hb-language") || "en", filter: "all", collection: "all", query: "", heroIndex: 0,
  admin: null, adminSection: "overview", notice: "", adminSearch: "", adminStatus: "all", mediaSearch: "", mediaUsage: "all", editor: null,
};

function persistCart() { localStorage.setItem("kdb-hb-cart", JSON.stringify(state.cart)); }
function cartCount() { return state.cart.reduce((sum, line) => sum + Number(line.quantity || 0), 0); }
function getProduct(id, source = state.store?.products || []) { return source.find((product) => product.id === id); }
function getVariant(product, variantId) { return product?.variants?.find((variant) => variant.id === variantId) || product?.variants?.[0]; }
function cartLines() { return state.cart.map((line) => { const product = getProduct(line.productId); const variant = getVariant(product, line.variantId); return product && variant ? { ...line, product, variant } : null; }).filter(Boolean); }
function publicSetting(path, fallback) { return path.split(".").reduce((value, key) => value?.[key], state.store?.settings) ?? fallback; }

function publicHeader() {
  return `<header class="site-header"><div class="header-signal"><span>KDB / ROOM EDIT / 02</span><span>${safe(state.store.settings.announcement)}</span><span>COD / 58 WILAYAS</span></div><div class="header-main"><a class="wordmark" href="#home" aria-label="KDB home"><i></i><strong>KDB</strong></a><nav aria-label="Store navigation"><a href="#shop">${label("shop")}</a><a href="#collections">${label("collections")}</a><a href="#projects">${label("projects")}</a><a href="#contact">${label("contact")}</a></nav><div class="header-actions"><button class="language-button" data-action="language">${label("language")}</button><button class="bag-button" data-action="bag" aria-label="Open bag">${icon("bag")}<span>${label("bag")}</span><b>${String(cartCount()).padStart(2, "0")}</b></button></div></div></header>`;
}

function productCard(product, index) {
  const price = product.variants?.[0]?.price ?? product.price;
  const available = product.variants?.some((variant) => variant.available !== false);
  return `<article class="product-card product-card--${index % 3}"><button class="product-image" data-action="product" data-product="${safe(product.id)}"><img src="${safe(product.image)}" alt="${safe(localized(product))}" loading="lazy"/><span>${label("details")} ${icon("arrow")}</span>${product.offer?.enabled && product.offer.label ? `<em>${safe(product.offer.label)}</em>` : ""}</button><div class="product-meta"><div><p>${safe(product.categoryId)} / ${safe(product.sku)}</p><h3>${safe(localized(product))}</h3><span>${safe(localized(product, "description"))}</span></div><div class="product-price"><small>${available ? label("cod") : "Unavailable"}</small><strong>${format(price)}</strong><button class="round-add" data-action="add" data-product="${safe(product.id)}" aria-label="${label("add")}">${icon("plus")}</button></div></div></article>`;
}

function hero() {
  const slides = state.store.content.heroSlides || [];
  const slide = slides[state.heroIndex % Math.max(slides.length, 1)] || {};
  const title = localized(slide, "title") || slide.title || "KDB";
  return `<section class="hero ${slide.textTone === "light" ? "hero--light" : ""}"><div class="hero-copy"><p class="eyebrow">${safe(localized(slide, "kicker") || slide.kicker || "THE KDB ROOM")}</p><h1>${safe(title).replace(/^(\S+)/, "<em>$1</em>")}</h1><p>${safe(localized(slide, "body") || slide.body || "")}</p><a class="button button--dark" href="${safe(slide.href || "#shop")}">${safe(localized(slide, "action") || slide.action || label("discover"))} ${icon("arrow")}</a><small>01 / ${String(slides.length || 1).padStart(2, "0")} — COD ONLY · 58 WILAYAS</small></div><figure class="hero-image"><img src="${safe(slide.image || state.store.products[0]?.image || "")}" alt="KDB material study"/><figcaption>FIELD NOTES / WARM LIGHT, QUIET MATERIAL</figcaption>${slides.length > 1 ? `<div class="hero-controls"><button data-action="hero-prev" aria-label="Previous hero">${icon("arrow")}</button><button data-action="hero-next" aria-label="Next hero">${icon("arrow")}</button>${publicSetting("presentation.heroDots", true) ? `<span>${slides.map((item, index) => `<button data-action="hero-dot" data-index="${index}" class="${index === state.heroIndex ? "is-active" : ""}" aria-label="Hero ${index + 1}"></button>`).join("")}</span>` : ""}</div>` : ""}</figure></section>`;
}

function shop() {
  const categories = state.store.categories.filter((category) => category.visible !== false);
  const products = state.store.products.filter((product) => {
    const haystack = `${product.name} ${product.nameAr || ""} ${product.description || ""} ${product.material || ""} ${(product.colors || []).map((item) => item.name).join(" ")}`.toLowerCase();
    return (state.filter === "all" || product.categoryId === state.filter) && (state.collection === "all" || (product.collectionIds || []).includes(state.collection)) && haystack.includes(state.query.toLowerCase());
  });
  return `<section id="shop" class="catalogue-section"><div class="section-head"><div><p class="eyebrow">THE CATALOGUE</p><h2>A small edit, <em>well held.</em></h2></div><span>${String(products.length).padStart(2, "0")} pieces</span></div><div class="catalogue-tools"><label class="search-input">${icon("search")}<input data-input="search" value="${safe(state.query)}" placeholder="${safe(label("search"))}"/></label><div class="filter-row" role="tablist"><button data-action="filter" data-filter="all" class="${state.filter === "all" ? "active" : ""}">${label("all")}</button>${categories.map((category) => `<button data-action="filter" data-filter="${safe(category.id)}" class="${state.filter === category.id ? "active" : ""}">${safe(localized(category))}</button>`).join("")}</div></div><div class="product-grid">${products.map(productCard).join("") || `<div class="empty"><h3>No pieces match this edit.</h3><p>Clear the filters or return to the full KDB catalogue.</p></div>`}</div></section>`;
}

function collections() {
  const collections = state.store.collections.filter((collection) => collection.visible !== false);
  return `<section id="collections" class="collection-section"><div class="section-head"><div><p class="eyebrow">COLLECTIONS</p><h2>Materials in <em>conversation.</em></h2></div><span>KDB / EDITS</span></div><div class="collection-grid">${collections.map((collection, index) => `<button class="collection-card collection-card--${index % 2}" data-action="collection" data-collection="${safe(collection.id)}"><img src="${safe(collection.image)}" alt="${safe(localized(collection))}"/><span><small>${String(collection.productIds?.length || 0).padStart(2, "0")} pieces</small><strong>${safe(localized(collection))}</strong><em>${safe(localized(collection, "description"))}</em></span></button>`).join("") || `<p class="empty">Collections will appear here when the owner publishes them.</p>`}</div></section>`;
}

function projects() {
  const visible = state.store.content.projects?.filter((project) => project.visible !== false) || [];
  if (!state.store.content.sectionVisibility.projects && !visible.length) return "";
  return `<section id="projects" class="projects-section"><div class="section-head"><div><p class="eyebrow">KDB / PROJECT NOTES</p><h2>Rooms made <em>more particular.</em></h2></div></div>${visible.length ? `<div class="project-grid">${visible.map((project) => `<article><img src="${safe(project.image || "")}" alt="${safe(localized(project))}"/><div><small>${safe(project.type || "KDB project")}</small><h3>${safe(localized(project))}</h3><p>${safe(localized(project, "description"))}</p></div></article>`).join("")}</div>` : `<div class="empty project-empty"><p>Projects are selected and published from the KDB owner room.</p></div>`}</section>`;
}

function about() {
  const content = state.store.content;
  const stats = content.statistics?.filter((item) => item.visible !== false) || [];
  return `<section id="about" class="about-band"><div><p class="eyebrow">KDB / MATERIAL NOTE</p><h2>${safe(localized(content.about, "title") || content.about.title).replace(/\b(rooms|غرف)\b/, "<em>$1</em>")}</h2></div><p>${safe(localized(content.about, "body") || content.about.body)}</p>${content.sectionVisibility.statistics !== false ? `<div class="stat-line">${stats.map((stat) => `<span><strong>${safe(stat.value)}</strong><small>${safe(stat.label)}</small></span>`).join("")}</div>` : ""}</section>`;
}

function contact() {
  const identity = state.store.settings.identity;
  return `<section id="contact" class="contact-section"><div><p class="eyebrow">KDB / CONTACT</p><h2>${label("contactTitle")}</h2><p>${label("contactBody")}</p></div><div class="contact-actions"><a href="tel:${safe(identity.contactPhone.replace(/\s/g, ""))}">${icon("truck")}<span><small>Studio phone</small><strong>${safe(identity.contactPhone)}</strong></span></a>${identity.whatsappUrl ? `<a href="${safe(identity.whatsappUrl)}" target="_blank" rel="noreferrer">${icon("arrow")}<span><small>WhatsApp</small><strong>Open conversation</strong></span></a>` : ""}<a href="mailto:${safe(identity.email)}">${icon("arrow")}<span><small>Email</small><strong>${safe(identity.email)}</strong></span></a></div></section>`;
}

function productDialog() {
  const product = getProduct(state.productId);
  if (!product) return "";
  const variant = getVariant(product);
  return `<div class="drawer-backdrop product-dialog-backdrop"><section class="product-dialog" role="dialog" aria-modal="true" aria-label="${safe(localized(product))}"><button class="icon-button" data-action="close-product" aria-label="Close">${icon("close")}</button><div class="product-dialog__gallery"><img src="${safe(product.image)}" alt="${safe(localized(product))}"/><div>${(product.gallery || []).map((url) => `<img src="${safe(url)}" alt=""/>`).join("")}</div></div><form id="product-detail-form" class="product-dialog__copy"><p class="eyebrow">${safe(product.categoryId)} / ${safe(product.sku)}</p><h2>${safe(localized(product))}</h2><p>${safe(localized(product, "description"))}</p><dl>${(product.attributes || []).map((item) => `<div><dt>${safe(item.label)}</dt><dd>${safe(item.value)}</dd></div>`).join("")}</dl>${product.colors?.length ? `<div class="colour-swatches">${product.colors.map((colour) => `<span title="${safe(colour.name)}" style="--swatch:${safe(colour.hex)}"></span>`).join("")}</div>` : ""}<label>Variant<select name="variantId">${product.variants.map((item) => `<option value="${safe(item.id)}" ${item.id === variant.id ? "selected" : ""} ${item.available === false || item.stock < 1 ? "disabled" : ""}>${safe(item.name)} — ${format(item.price)}</option>`).join("")}</select></label>${product.customSizeEnabled ? `<label>Custom-size note<input name="customSize" maxlength="120" placeholder="Optional size note"/></label>` : ""}<div class="product-dialog__buy"><strong>${format(variant.price)}</strong><button class="button button--dark" type="submit">${label("add")} ${icon("arrow")}</button></div><small>COD only · Delivery selected at checkout.</small></form></section></div>`;
}

function wilayaOptions() { return `<option value="">Select wilaya</option>${WILAYAS.map((wilaya) => `<option value="${wilaya.code}">${wilaya.code} — ${safe(wilaya.ar)}</option>`).join("")}`; }
function bagDrawer() {
  const lines = cartLines();
  const subtotal = lines.reduce((sum, line) => sum + line.variant.price * line.quantity, 0);
  if (state.order) return `<div class="drawer-backdrop"><aside class="bag-drawer confirmation"><button class="icon-button" data-action="close-bag" aria-label="Close">${icon("close")}</button><p class="eyebrow">COD ORDER RECEIVED</p><h2>Your room is<br/><em>set aside.</em></h2><p>Order <strong>${safe(state.order.id)}</strong> will be confirmed by phone. Payment is cash on delivery only.</p><dl><div><dt>Wilaya</dt><dd>${safe(state.order.wilayaName)}</dd></div><div><dt>Delivery</dt><dd>${state.order.deliveryType === "domicile" ? `Domicile · ${safe(state.order.baladiya)}` : "Pickup point / Stop Desk"}</dd></div><div><dt>Total</dt><dd>${format(state.order.total)}</dd></div></dl><button class="button button--dark" data-action="close-bag">Continue browsing ${icon("arrow")}</button></aside></div>`;
  return `<div class="drawer-backdrop"><aside class="bag-drawer" role="dialog" aria-modal="true" aria-label="KDB bag"><header><div><p class="eyebrow">YOUR BAG / ${String(cartCount()).padStart(2, "0")}</p><h2>${lines.length ? "Set aside." : "Nothing held."}</h2></div><button class="icon-button" data-action="close-bag" aria-label="Close bag">${icon("close")}</button></header>${lines.length ? `<div class="bag-lines">${lines.map((line) => `<article><img src="${safe(line.product.image)}" alt=""/><div><small>${safe(line.product.categoryId)}</small><h3>${safe(localized(line.product))}</h3><span>${safe(line.variant.name)} · ${format(line.variant.price)} · COD</span><div class="quantity"><button data-action="quantity" data-key="${safe(line.productId)}:${safe(line.variantId)}" data-delta="-1" aria-label="Reduce quantity">${icon("minus")}</button><b>${line.quantity}</b><button data-action="quantity" data-key="${safe(line.productId)}:${safe(line.variantId)}" data-delta="1" aria-label="Increase quantity">${icon("plus")}</button></div></div><strong>${format(line.variant.price * line.quantity)}</strong></article>`).join("")}</div><div class="bag-total"><span>Material total</span><strong>${format(subtotal)}</strong></div><form id="order-form" class="cod-form"><p class="cod-only">${icon("truck")} ${label("cod")}: <strong>Cash on delivery (COD)</strong></p><div class="form-grid"><label>${label("fullName")}<input name="fullName" autocomplete="name" required minlength="3"/></label><label>${label("phone")}<input name="phone" type="tel" inputmode="tel" autocomplete="tel" required pattern="[0-9+(). -]{8,24}"/></label><label>${label("wilaya")}<select name="wilayaCode" required>${wilayaOptions()}</select></label></div><div class="delivery-options"><label class="delivery-option"><input name="deliveryType" type="radio" value="stop_desk" checked/><span><b>${icon("truck")} ${label("stopDesk")}</b><small>Collect from the selected wilaya’s delivery desk.</small></span></label><label class="delivery-option"><input name="deliveryType" type="radio" value="domicile"/><span><b>${icon("truck")} ${label("domicile")}</b><small>Select your baladiya after choosing a wilaya.</small></span></label></div><label id="baladiya-field" class="is-hidden">${label("baladiya")}<select name="baladiya"><option value="">Select wilaya first</option></select></label><p id="form-error" class="form-error" role="alert"></p><button class="button button--dark" type="submit">${label("checkout")} ${icon("arrow")}</button><small class="form-footnote">We collect only your full name, phone number and delivery selection to confirm your COD order.</small></form>` : `<div class="empty"><p>Choose a material study and it will appear here.</p><button class="button button--dark" data-action="close-bag">Return to catalogue ${icon("arrow")}</button></div>`}</aside></div>`;
}

function storefront() { return `${publicHeader()}<main id="home" dir="${state.lang === "ar" ? "rtl" : "ltr"}">${state.store.content.sectionVisibility.hero !== false ? hero() : ""}${state.store.content.sectionVisibility.catalogue !== false ? shop() : ""}${state.store.content.sectionVisibility.collections !== false ? collections() : ""}${projects()}${state.store.content.sectionVisibility.about !== false ? about() : ""}${state.store.content.sectionVisibility.contact !== false ? contact() : ""}</main><footer class="site-footer"><span>KDB / OBJECTS FOR THE EVERYDAY</span><span>COD / ALGERIA</span></footer>${state.bagOpen ? bagDrawer() : ""}${state.productId ? productDialog() : ""}`; }

function adminGate() {
  return `${publicHeader()}<main class="admin-gate"><div><p class="eyebrow">KDB / OWNER CONTROL</p><h1>Control the<br/><em>whole room.</em></h1><p>The KDB owner room brings COD operations, catalogue governance, content, media, delivery, insights and data tools into one protected console.</p><form id="admin-login"><label>Owner access code<input type="password" name="token" required autocomplete="current-password"/></label><p class="form-error" id="admin-error"></p><button class="button button--dark" type="submit">Enter control room ${icon("arrow")}</button></form></div><img src="${safe(state.store.products[0]?.image || "")}" alt="KDB textile detail"/></main>`;
}

function metric(labelText, value, detail, iconName = "chart") { return `<article class="metric">${icon(iconName)}<small>${safe(labelText)}</small><strong>${safe(value)}</strong><span>${safe(detail)}</span></article>`; }
function adminShell() {
  const nav = [["overview", "Overview", "chart"], ["orders", "COD orders", "bag"], ["delivery", "Delivery", "truck"], ["catalogue", "Catalogue", "sliders"], ["collections", "Collections", "menu"], ["hero", "Hero studio", "image"], ["content", "Content", "menu"], ["media", "Media library", "image"], ["insights", "Insights", "chart"], ["settings", "Store settings", "sliders"], ["activity", "Activity & data", "database"], ["team", "Team directory", "shield"]];
  const pages = { overview: adminOverview, orders: adminOrders, delivery: adminDelivery, catalogue: adminCatalogue, collections: adminCollections, hero: adminHero, content: adminContent, media: adminMedia, insights: adminInsights, settings: adminSettings, activity: adminActivity, team: adminTeam };
  const page = (pages[state.adminSection] || adminOverview)(state.admin);
  return `<main class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="#home"><i></i><strong>KDB</strong><span>OWNER ROOM</span></a><nav>${nav.map(([key, textValue, ico]) => `<button data-action="admin-nav" data-section="${key}" class="${state.adminSection === key ? "active" : ""}">${icon(ico)}<span>${textValue}</span></button>`).join("")}</nav><div><span>AUTHORIZED / OWNER</span><button data-action="admin-logout">${icon("logout")}<span>Lock console</span></button></div></aside><section class="admin-main"><header class="admin-header"><div><p class="eyebrow">KDB / OWNER CONTROL / ${safe(state.adminSection)}</p><h1>${safe((nav.find(([key]) => key === state.adminSection) || ["", "Room control"])[1])}</h1></div><a href="#home">View storefront ${icon("arrow")}</a></header>${state.notice ? `<p class="admin-notice">${safe(state.notice)}</p>` : ""}${page}</section></main>`;
}

function adminOverview(store) {
  const analytics = computeAnalytics(store);
  return `<section class="admin-content"><div class="metrics">${metric("Published studies", String(analytics.publishedProducts).padStart(2, "0"), "Live on KDB", "eye")}${metric("COD requests", String(analytics.orderCount).padStart(2, "0"), `${analytics.requestedOrders} need confirmation`, "bag")}${metric("Confirmed value", format(analytics.confirmedRevenue), "Current ledger", "chart")}${metric("Low stock", String(analytics.lowStock.length).padStart(2, "0"), "Needs attention", "sliders")}${metric("Wilayas live", `${58 - analytics.disabledWilayas.length}/58`, "Delivery coverage", "truck")}</div><div class="admin-panel split"><div><p class="eyebrow">TODAY / OPERATIONAL FOCUS</p><h2>Keep the whole <em>room moving.</em></h2><p>Confirm COD requests, prepare Stop Desk or domicile delivery, keep stock truthful, and publish only the material studies ready for the public edit.</p></div><div class="rule-list"><span>${icon("check")} Confirm customer by phone</span><span>${icon("check")} Prepare wilaya-specific delivery</span><span>${icon("check")} Advance the fulfilment ledger</span><span>${icon("check")} Review catalogue health</span></div></div><div class="admin-two"><section class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">CATALOGUE HEALTH</p><h3>Attention queue</h3></div></div>${analytics.lowStock.length ? `<ul class="compact-list">${analytics.lowStock.slice(0, 6).map((item) => `<li><span>${safe(item.product)} / ${safe(item.variant)}</span><b>${item.stock} left</b></li>`).join("")}</ul>` : "<p class='muted'>No low-stock variants.</p>"}</section><section class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">LATEST ACTIVITY</p><h3>Owner log</h3></div></div>${store.activity.length ? `<ul class="compact-list">${store.activity.slice(0, 6).map((item) => `<li><span>${safe(item.detail)}</span><small>${new Date(item.createdAt).toLocaleString()}</small></li>`).join("")}</ul>` : "<p class='muted'>Changes will be recorded here.</p>"}</section></div></section>`;
}

function adminOrders(store) {
  const statuses = ["requested", "confirmed", "awaiting_supply", "processing", "ready_to_ship", "shipped", "delivered", "cancelled", "returned"];
  const filtered = store.orders.filter((order) => (state.adminStatus === "all" || order.status === state.adminStatus) && `${order.id} ${order.fullName} ${order.phone} ${order.wilayaName}`.toLowerCase().includes(state.adminSearch.toLowerCase()));
  return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">COD ORDER LEDGER</p><h2>Delivery-ready requests</h2></div><span>${store.orders.length} requests</span></div><div class="operation-filter"><label>${icon("search")}<input data-input="order-search" value="${safe(state.adminSearch)}" placeholder="Search name, phone, order or wilaya"/></label><select data-input="order-status-filter"><option value="all">All statuses</option>${statuses.map((status) => `<option value="${status}" ${state.adminStatus === status ? "selected" : ""}>${status.replaceAll("_", " ")}</option>`).join("")}</select></div>${filtered.length ? `<div class="data-table order-table"><div class="table-head"><span>Customer / contact</span><span>Delivery & items</span><span>Total</span><span>Operation</span></div>${filtered.map((order) => `<form data-order-form="${safe(order.id)}"><div><strong>${safe(order.fullName)}</strong><span>${safe(order.phone)} · ${safe(order.id)}</span><small>${safe(order.source || "storefront")}${order.campaign ? ` · ${safe(order.campaign)}` : ""}</small></div><div><strong>${safe(order.wilayaCode)} — ${safe(order.wilayaName)}</strong><span>${order.deliveryType === "domicile" ? `Domicile · ${safe(order.baladiya)}` : "Pickup point / Stop Desk"}</span><small>${order.lines.map((line) => `${safe(line.name)} ×${line.quantity}`).join(" · ")}</small></div><strong>${format(order.total)}</strong><div><select name="status">${statuses.map((status) => `<option value="${status}" ${order.status === status ? "selected" : ""}>${status.replaceAll("_", " ")}</option>`).join("")}</select><textarea name="notes" placeholder="Operational notes">${safe(order.notes || "")}</textarea><button class="table-save" type="submit">Save</button></div></form>`).join("")}</div>` : `<div class="admin-empty"><h2>No matching COD orders.</h2><p>New checkout requests arrive here with their order snapshot and delivery context.</p></div>`}</section>`;
}

function adminDelivery(store) {
  return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">58 WILAYAS / DELIVERY MATRIX</p><h2>Route every order.</h2></div><button class="button button--ghost" data-action="delivery-reset">Reset baseline</button></div><form id="delivery-bulk" class="admin-panel bulk-form"><div><p class="eyebrow">BULK DELIVERY CHANGE</p><h3>Adjust a delivery mode across the matrix.</h3></div><label>Mode<select name="mode"><option value="stop_desk">Stop Desk</option><option value="domicile">Domicile</option></select></label><label>Change in DA<input type="number" name="delta" value="0" required/></label><label class="check">Only currently active wilayas<input type="checkbox" name="enabledOnly"/></label><button class="button button--dark" type="submit">Apply change ${icon("arrow")}</button></form><div class="data-table delivery-table"><div class="table-head"><span>Wilaya</span><span>Stop Desk fee</span><span>Domicile fee</span><span>Availability</span></div>${store.deliveryRules.map((rule) => `<form data-delivery-form="${rule.code}"><span><b>${rule.code}</b> ${safe(rule.name)}</span><label><input name="stopDeskFee" type="number" min="0" value="${rule.stopDeskFee}"/><small>DA</small></label><label><input name="domicileFee" type="number" min="0" value="${rule.domicileFee}"/><small>DA</small></label><label class="availability"><input name="enabled" type="checkbox" ${rule.enabled ? "checked" : ""}/> Active</label><label class="availability"><input name="free" type="checkbox" ${rule.free ? "checked" : ""}/> Free</label><button class="table-save" type="submit">Save</button></form>`).join("")}</div></section>`;
}

function advancedProduct(product) {
  return `<details class="advanced-editor"><summary>Variants, gallery, colour, attributes and publication</summary><div class="editor-fields"><label>Gallery URLs (JSON)<textarea name="gallery">${jsonText(product.gallery)}</textarea></label><label>Variants (JSON)<textarea name="variants">${jsonText(product.variants)}</textarea></label><label>Colour swatches (JSON)<textarea name="colors">${jsonText(product.colors)}</textarea></label><label>Attributes (JSON)<textarea name="attributes">${jsonText(product.attributes)}</textarea></label><label>Collection IDs (JSON)<textarea name="collectionIds">${jsonText(product.collectionIds)}</textarea></label><label>Tags (JSON)<textarea name="tags">${jsonText(product.tags)}</textarea></label><label>Publish at<input name="publishAt" type="datetime-local" value="${toDateTimeInput(product.publishAt)}"/></label><label>Unpublish at<input name="unpublishAt" type="datetime-local" value="${toDateTimeInput(product.unpublishAt)}"/></label><label>Offer label<input name="offerLabel" value="${safe(product.offer?.label || "")}"/></label><label class="check">Offer enabled<input name="offerEnabled" type="checkbox" ${product.offer?.enabled ? "checked" : ""}/></label><label class="check">Custom size enabled<input name="customSizeEnabled" type="checkbox" ${product.customSizeEnabled ? "checked" : ""}/></label><label class="check">Lifestyle view enabled<input name="lifestyleEnabled" type="checkbox" ${product.lifestyleEnabled !== false ? "checked" : ""}/></label><label class="check">Discovery enabled<input name="discoveryEnabled" type="checkbox" ${product.discoveryEnabled !== false ? "checked" : ""}/></label><label class="check">Visible in catalogue<input name="visible" type="checkbox" ${product.visible !== false ? "checked" : ""}/></label><label>Arabic name<input name="nameAr" value="${safe(product.nameAr || "")}"/></label><label>Arabic description<textarea name="descriptionAr">${safe(product.descriptionAr || "")}</textarea></label></div></details>`;
}

function productForm(product) {
  return `<form class="product-editor" data-product-form="${safe(product.id || "new")}"><div class="product-editor__head"><div><p class="eyebrow">${product.id ? "CATALOGUE RECORD" : "NEW STUDY"}</p><h3>${safe(product.name || "Create material study")}</h3></div><button type="button" class="icon-button" data-action="close-editor">${icon("close")}</button></div><div class="editor-fields"><label>Name<input name="name" value="${safe(product.name || "")}" required/></label><label>Category<select name="categoryId">${state.admin.categories.map((category) => `<option value="${safe(category.id)}" ${product.categoryId === category.id ? "selected" : ""}>${safe(category.name)}</option>`).join("")}</select></label><label>SKU<input name="sku" value="${safe(product.sku || "")}" required/></label><label>Material<input name="material" value="${safe(product.material || "")}"/></label><label>Price DA<input name="price" type="number" min="0" value="${Number(product.price || 0)}" required/></label><label>Stock<input name="stock" type="number" min="0" value="${Number(product.stock || 0)}" required/></label><label>Status<select name="status">${["draft", "published", "archived"].map((status) => `<option value="${status}" ${product.status === status ? "selected" : ""}>${status}</option>`).join("")}</select></label><label>Position<input name="position" type="number" min="0" value="${Number(product.position || 0)}"/></label><label class="wide">Main image URL<input name="image" type="url" value="${safe(product.image || "")}" required/></label><label class="wide">Hover image URL<input name="hoverImage" type="url" value="${safe(product.hoverImage || product.image || "")}"/></label><label class="wide">Description<textarea name="description">${safe(product.description || "")}</textarea></label><label class="check">Feature on home<input name="featured" type="checkbox" ${product.featured ? "checked" : ""}/></label></div>${advancedProduct(product)}<button class="button button--dark" type="submit">Save study ${icon("arrow")}</button></form>`;
}

function adminCatalogue(store) { const editor = state.editor?.kind === "product" ? state.editor.record : null; return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">CATALOGUE / INVENTORY</p><h2>Material studies</h2></div><button class="button button--dark" data-action="new-product">Add study ${icon("plus")}</button></div>${editor ? productForm(editor) : ""}<div class="product-admin-grid">${store.products.sort((a,b)=>a.position-b.position).map((product) => `<article class="catalogue-row"><img src="${safe(product.image)}" alt=""/><div><small>${safe(product.status)} · ${safe(product.categoryId)}</small><h3>${safe(product.name)}</h3><p>${format(product.price)} · ${product.stock} units · ${(product.variants || []).length} variants</p></div><div><button class="button button--ghost" data-action="edit-product" data-product="${safe(product.id)}">Edit ${icon("arrow")}</button><button class="text-danger" data-action="delete" data-kind="products" data-id="${safe(product.id)}">Archive / remove</button></div></article>`).join("")}</div></section>`; }

function recordForm(kind, record) {
  const productIds = record.productIds || [];
  return `<form class="record-form" data-record-form="${kind}" data-record-id="${safe(record.id || "new")}"><div class="editor-fields"><label>Name<input name="name" value="${safe(record.name || "")}" required/></label><label>Arabic name<input name="nameAr" value="${safe(record.nameAr || "")}"/></label><label>Position<input name="position" type="number" min="0" value="${Number(record.position || 0)}"/></label><label class="check">Visible<input name="visible" type="checkbox" ${record.visible !== false ? "checked" : ""}/></label><label class="wide">Image URL<input name="image" type="url" value="${safe(record.image || "")}" ${kind === "collections" ? "required" : ""}/></label><label class="wide">Description<textarea name="description">${safe(record.description || "")}</textarea></label><label class="wide">Arabic description<textarea name="descriptionAr">${safe(record.descriptionAr || "")}</textarea></label>${kind === "categories" ? `<label>Parent category ID<input name="parentId" value="${safe(record.parentId || "")}"/></label><label class="check">Show in navigation<input name="navigation" type="checkbox" ${record.navigation !== false ? "checked" : ""}/></label><label class="check">Show colour filter<input name="colorFilterVisible" type="checkbox" ${record.colorFilterVisible !== false ? "checked" : ""}/></label>` : `<label class="wide">Product IDs (JSON)<textarea name="productIds">${jsonText(productIds)}</textarea></label>`}</div><button class="button button--dark" type="submit">Save ${kind.slice(0, -1)} ${icon("arrow")}</button></form>`;
}

function adminCollections(store) {
  const editor = state.editor?.kind === "category" || state.editor?.kind === "collection" ? state.editor : null;
  return `<section class="admin-content"><div class="admin-two"><div class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">CATEGORIES</p><h2>Navigation and hierarchy</h2></div><button class="button button--ghost" data-action="new-category">Add category</button></div>${editor?.kind === "category" ? recordForm("categories", editor.record) : ""}<div class="record-list">${store.categories.map((record) => `<article><img src="${safe(record.image || "")}" alt=""/><div><strong>${safe(record.name)}</strong><span>${safe(record.id)} · ${record.visible !== false ? "visible" : "hidden"}</span></div><button data-action="edit-category" data-id="${safe(record.id)}">Edit</button><button class="text-danger" data-action="delete" data-kind="categories" data-id="${safe(record.id)}">Remove</button></article>`).join("")}</div></div><div class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">COLLECTIONS</p><h2>Public edits</h2></div><button class="button button--ghost" data-action="new-collection">Add collection</button></div>${editor?.kind === "collection" ? recordForm("collections", editor.record) : ""}<div class="record-list">${store.collections.map((record) => `<article><img src="${safe(record.image || "")}" alt=""/><div><strong>${safe(record.name)}</strong><span>${record.productIds?.length || 0} connected products</span></div><button data-action="edit-collection" data-id="${safe(record.id)}">Edit</button><button class="text-danger" data-action="delete" data-kind="collections" data-id="${safe(record.id)}">Remove</button></article>`).join("")}</div></div></div></section>`;
}

function heroForm(slide) {
  return `<form class="hero-editor" data-hero-form="${safe(slide.id || "new")}"><div class="editor-fields"><label>Kicker<input name="kicker" value="${safe(slide.kicker || "")}"/></label><label>Arabic kicker<input name="kickerAr" value="${safe(slide.kickerAr || "")}"/></label><label class="wide">Title<input name="name" value="${safe(slide.title || slide.name || "")}" required/></label><label class="wide">Arabic title<input name="nameAr" value="${safe(slide.titleAr || slide.nameAr || "")}"/></label><label class="wide">Body<textarea name="description">${safe(slide.body || slide.description || "")}</textarea></label><label class="wide">Arabic body<textarea name="descriptionAr">${safe(slide.bodyAr || slide.descriptionAr || "")}</textarea></label><label>CTA label<input name="action" value="${safe(slide.action || "")}"/></label><label>Arabic CTA<input name="actionAr" value="${safe(slide.actionAr || "")}"/></label><label>Destination<input name="href" value="${safe(slide.href || "#shop")}"/></label><label>External URL<input name="externalUrl" type="url" value="${safe(slide.externalUrl || "")}"/></label><label>Text contrast<select name="textTone"><option value="dark" ${slide.textTone === "dark" ? "selected" : ""}>Dark ink</option><option value="light" ${slide.textTone === "light" ? "selected" : ""}>Light canvas</option></select></label><label>Sort order<input name="position" type="number" min="0" value="${Number(slide.sortOrder ?? slide.position ?? 0)}"/></label><label class="wide">Desktop image URL<input name="image" type="url" value="${safe(slide.image || "")}" required/></label><label class="wide">Mobile image URL<input name="mobileImage" type="url" value="${safe(slide.mobileImage || "")}"/></label><label class="wide">Fallback image URL<input name="fallbackImage" type="url" value="${safe(slide.fallbackImage || "")}"/></label><label class="check">Enabled<input name="enabled" type="checkbox" ${slide.enabled !== false ? "checked" : ""}/></label></div><button class="button button--dark" type="submit">Save hero slide ${icon("arrow")}</button></form>`;
}

function adminHero(store) { const editor = state.editor?.kind === "hero" ? state.editor.record : null; return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">HERO STUDIO</p><h2>Art direct the first room.</h2></div><button class="button button--dark" data-action="new-hero">Add slide ${icon("plus")}</button></div><div class="admin-panel presentation-note"><p>Hero display settings are controlled from <b>Store settings</b>. Each slide keeps desktop, mobile and fallback imagery, bilingual copy, destination, contrast and ordering.</p></div>${editor ? heroForm(editor) : ""}<div class="hero-admin-grid">${store.content.heroSlides.map((slide) => `<article><img src="${safe(slide.image)}" alt=""/><div><small>${slide.enabled ? "enabled" : "hidden"} · ${slide.sortOrder}</small><h3>${safe(slide.title)}</h3><p>${safe(slide.action || "No action")}</p></div><button class="button button--ghost" data-action="edit-hero" data-id="${safe(slide.id)}">Edit</button><button class="text-danger" data-action="delete-hero" data-id="${safe(slide.id)}">Remove</button></article>`).join("")}</div></section>`; }

function adminContent(store) {
  const content = store.content;
  return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">PUBLIC CONTENT</p><h2>Showroom, projects and proof.</h2></div><span>Content without fabricated customer reviews</span></div><form id="content-form" class="settings-form"><div class="editor-fields"><label class="wide">About title<input name="aboutTitle" value="${safe(content.about.title || "")}"/></label><label class="wide">About text<textarea name="aboutBody">${safe(content.about.body || "")}</textarea></label><label class="wide">Arabic about title<input name="aboutTitleAr" value="${safe(content.about.titleAr || "")}"/></label><label class="wide">Arabic about text<textarea name="aboutBodyAr">${safe(content.about.bodyAr || "")}</textarea></label><label class="wide">Projects (JSON)<textarea name="projects">${jsonText(content.projects)}</textarea></label><label class="wide">Statistics (JSON)<textarea name="statistics">${jsonText(content.statistics)}</textarea></label><label class="wide">Certifications (JSON)<textarea name="certifications">${jsonText(content.certifications)}</textarea></label><label class="wide">Section visibility (JSON)<textarea name="sectionVisibility">${jsonText(content.sectionVisibility)}</textarea></label></div><p class="muted">Use projects, statistics and certifications for owner-authored factual content. Testimonials, ratings and reviews are intentionally excluded.</p><button class="button button--dark" type="submit">Save public content ${icon("arrow")}</button></form></section>`;
}

function adminMedia(store) {
  const media = store.media.filter((asset) => (state.mediaUsage === "all" || asset.usage === state.mediaUsage) && `${asset.name} ${asset.tags?.join(" ")} ${asset.section}`.toLowerCase().includes(state.mediaSearch.toLowerCase()));
  return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">MEDIA LIBRARY</p><h2>Reuse assets with context.</h2></div><span>URL-backed assets</span></div><form id="media-form" class="media-form"><label>Name<input name="name" required/></label><label>Image URL<input name="url" type="url" required/></label><label>Usage<select name="usage">${["hero", "product", "collection", "project", "identity", "other"].map((value) => `<option value="${value}">${value}</option>`).join("")}</select></label><label>Section<input name="section" placeholder="homepage"/></label><label>Provider<input name="provider" value="external"/></label><label>Tags, comma separated<input name="tags" placeholder="hero, warm, room"/></label><button class="button button--dark" type="submit">Add media ${icon("plus")}</button></form><div class="operation-filter"><label>${icon("search")}<input data-input="media-search" value="${safe(state.mediaSearch)}" placeholder="Search media"/></label><select data-input="media-usage-filter"><option value="all">All uses</option>${["hero", "product", "collection", "project", "identity", "other"].map((value) => `<option value="${value}" ${state.mediaUsage === value ? "selected" : ""}>${value}</option>`).join("")}</select></div><div class="media-grid">${media.map((asset) => `<article><img src="${safe(asset.url)}" alt=""/><div><small>${safe(asset.usage)} · ${safe(asset.provider)}</small><h3>${safe(asset.name)}</h3><p>${safe((asset.tags || []).join(" · "))}</p></div><button class="text-danger" data-action="delete" data-kind="media" data-id="${safe(asset.id)}">Remove</button></article>`).join("") || "<p class='empty'>No media matches the selected filters.</p>"}</div></section>`;
}

function adminInsights(store) { const analytics = computeAnalytics(store); return `<section class="admin-content"><div class="metrics">${metric("All orders", analytics.orderCount, "COD requests", "bag")}${metric("Inventory", analytics.totalUnits, "Units across variants", "sliders")}${metric("Media assets", analytics.mediaCount, "Reusable library", "image")}${metric("Disabled delivery", analytics.disabledWilayas.length, "Wilayas unavailable", "truck")}</div><div class="admin-two"><section class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">ORDER VOLUME</p><h3>Lifecycle distribution</h3></div></div><div class="bar-list">${Object.entries(analytics.byStatus).map(([status, amount]) => `<div><span>${safe(status.replaceAll("_", " "))}</span><b style="--bar:${Math.max(4, Math.min(100, Number(amount) * 12))}%">${amount}</b></div>`).join("")}</div></section><section class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">CATALOGUE HEALTH</p><h3>Publication signals</h3></div></div><ul class="compact-list"><li><span>Draft studies</span><b>${analytics.catalogueHealth.draftProducts}</b></li><li><span>Hidden studies</span><b>${analytics.catalogueHealth.hiddenProducts}</b></li><li><span>Missing image records</span><b>${analytics.catalogueHealth.missingImage}</b></li><li><span>Scheduled publication</span><b>${analytics.scheduledProducts.length}</b></li></ul></section></div><section class="admin-panel"><div class="admin-panel__head"><div><p class="eyebrow">LOW-STOCK SIGNAL</p><h3>Variants requiring review</h3></div></div>${analytics.lowStock.length ? `<div class="record-list">${analytics.lowStock.map((item) => `<article><div><strong>${safe(item.product)}</strong><span>${safe(item.variant)} · ${safe(item.sku)}</span></div><b>${item.stock} remaining</b></article>`).join("")}</div>` : "<p class='muted'>No low-stock variants.</p>"}</section></section>`; }

function adminSettings(store) {
  const settings = store.settings;
  return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">STORE SETTINGS</p><h2>Identity, delivery and consent.</h2></div><span>Private owner configuration</span></div><form id="settings-form" class="settings-form"><div class="editor-fields"><label>Announcement<input name="announcement" value="${safe(settings.announcement)}"/></label><label class="check">Accept COD orders<input name="storeOpen" type="checkbox" ${settings.storeOpen ? "checked" : ""}/></label><label>Store name<input name="storeName" value="${safe(settings.identity.storeName)}"/></label><label>Studio phone<input name="contactPhone" value="${safe(settings.identity.contactPhone)}"/></label><label>Email<input name="email" type="email" value="${safe(settings.identity.email)}"/></label><label>WhatsApp URL<input name="whatsappUrl" type="url" value="${safe(settings.identity.whatsappUrl)}"/></label><label>Privacy route<input name="privacyUrl" value="${safe(settings.identity.privacyUrl)}"/></label><label>Terms route<input name="termsUrl" value="${safe(settings.identity.termsUrl)}"/></label><label>Hero interval ms<input name="heroInterval" type="number" min="2000" max="30000" value="${Number(settings.presentation.heroInterval)}"/></label><label>Free delivery threshold DA<input name="freeDeliveryThreshold" type="number" min="0" value="${Number(settings.delivery.freeDeliveryThreshold)}"/></label><label>Handling guidance<input name="handlingDays" value="${safe(settings.delivery.handlingDays)}"/></label><label class="wide">Fulfilment message<textarea name="fulfilmentMessage">${safe(settings.delivery.fulfilmentMessage)}</textarea></label><label class="wide">Identity and social configuration (JSON)<textarea name="identityJson">${jsonText(settings.identity)}</textarea></label><label class="wide">Presentation controls (JSON)<textarea name="presentationJson">${jsonText(settings.presentation)}</textarea></label><label class="wide">Catalogue experience (JSON)<textarea name="catalogJson">${jsonText(settings.catalog)}</textarea></label><label class="wide">Consent and marketing configuration (JSON)<textarea name="marketingJson">${jsonText(settings.marketing)}</textarea></label><label class="wide">SEO configuration (JSON)<textarea name="seoJson">${jsonText(settings.seo)}</textarea></label></div><p class="muted">Marketing identifiers are stored as inert configuration. Do not enter credentials or private API keys in these fields.</p><button class="button button--dark" type="submit">Save store settings ${icon("arrow")}</button></form></section>`;
}

function adminActivity(store) { return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">ACTIVITY & DATA TOOLS</p><h2>Operational memory.</h2></div><span>${store.activity.length} latest entries</span></div><div class="admin-two"><section class="admin-panel"><p class="eyebrow">JSON BACKUP</p><h3>Export a recovery copy.</h3><p class="muted">The exported JSON contains operational settings, catalogue and order records. Store it securely.</p><button class="button button--dark" data-action="backup">Download backup ${icon("database")}</button></section><section class="admin-panel"><p class="eyebrow">RESTORE</p><h3>Restore an owner backup.</h3><p class="muted">A restore replaces the local development repository after schema normalization.</p><input id="restore-file" type="file" accept="application/json"/><button class="button button--ghost" data-action="restore">Restore selected backup</button></section></div><div class="activity-list">${store.activity.length ? store.activity.map((entry) => `<article><span>${safe(entry.type)}</span><strong>${safe(entry.detail)}</strong><small>${safe(entry.actor || "owner")}</small><time>${new Date(entry.createdAt).toLocaleString()}</time></article>`).join("") : "<div class='admin-empty'><h2>No changes yet.</h2><p>Catalogue, delivery, order, media and settings changes will be recorded here.</p></div>"}</div></section>`; }

function adminTeam(store) { return `<section class="admin-content"><div class="admin-panel__head"><div><p class="eyebrow">TEAM DIRECTORY</p><h2>Operational contacts.</h2></div><span>Owner access remains token-protected</span></div><form id="team-form" class="media-form"><label>Name<input name="name" required/></label><label>Operational role<input name="role" value="Operator" required/></label><label>Phone<input name="phone"/></label><label class="check">Active<input name="active" type="checkbox" checked/></label><button class="button button--dark" type="submit">Add contact ${icon("plus")}</button></form><div class="record-list team-list">${store.team.map((member) => `<article><div><strong>${safe(member.name)}</strong><span>${safe(member.role)}${member.phone ? ` · ${safe(member.phone)}` : ""}</span></div><small>${member.active ? "active" : "inactive"}</small>${member.id !== "owner" ? `<button class="text-danger" data-action="delete" data-kind="team" data-id="${safe(member.id)}">Remove</button>` : ""}</article>`).join("")}</div><div class="admin-panel presentation-note"><p>Directory roles document day-to-day responsibilities. They do not create login rights; access stays restricted to the configured owner token until a dedicated identity system is added.</p></div></section>`; }

function computeAnalytics(store) {
  const active = store.products.filter((product) => product.status !== "archived");
  const lowStock = active.flatMap((product) => product.variants.filter((variant) => variant.stock <= 3).map((variant) => ({ product: product.name, variant: variant.name, sku: variant.sku, stock: variant.stock })));
  const confirmed = new Set(["confirmed", "awaiting_supply", "processing", "ready_to_ship", "shipped", "delivered"]);
  const statuses = ["requested", "confirmed", "awaiting_supply", "processing", "ready_to_ship", "shipped", "delivered", "cancelled", "returned"];
  return { publishedProducts: active.filter((product) => product.status === "published" && product.visible !== false).length, totalUnits: active.reduce((sum, product) => sum + product.variants.reduce((inner, variant) => inner + Number(variant.stock || 0), 0), 0), orderCount: store.orders.length, requestedOrders: store.orders.filter((order) => order.status === "requested").length, confirmedRevenue: store.orders.filter((order) => confirmed.has(order.status)).reduce((sum, order) => sum + Number(order.total || 0), 0), lowStock, disabledWilayas: store.deliveryRules.filter((rule) => !rule.enabled), byStatus: Object.fromEntries(statuses.map((status) => [status, store.orders.filter((order) => order.status === status).length])), scheduledProducts: store.products.filter((product) => product.publishAt || product.unpublishAt), mediaCount: store.media.length, catalogueHealth: { draftProducts: active.filter((product) => product.status === "draft").length, hiddenProducts: active.filter((product) => product.visible === false).length, missingImage: active.filter((product) => !product.image).length } };
}

function toDateTimeInput(value) { return value ? new Date(value).toISOString().slice(0, 16) : ""; }
function render() { app.innerHTML = location.hash === "#admin" ? (state.admin ? adminShell() : adminGate()) : storefront(); bind(); }

function addProduct(id, variantId) {
  const product = getProduct(id); const variant = getVariant(product, variantId);
  if (!product || !variant || variant.available === false || (variant.stock !== undefined && variant.stock < 1)) return;
  const existing = state.cart.find((line) => line.productId === id && line.variantId === variant.id);
  const permittedQuantity = Math.min(8, variant.stock === undefined ? 8 : variant.stock);
  if (existing) existing.quantity = Math.min(existing.quantity + 1, permittedQuantity); else state.cart.push({ productId: id, variantId: variant.id, quantity: 1 });
  persistCart(); state.bagOpen = true; state.productId = null; render();
}

function updateBaladiya() {
  const form = document.querySelector("#order-form"); if (!form) return;
  const code = form.wilayaCode.value; const domicile = form.deliveryType.value === "domicile";
  const wrapper = document.querySelector("#baladiya-field"); const select = form.baladiya;
  wrapper.classList.toggle("is-hidden", !domicile); select.required = domicile;
  select.innerHTML = `<option value="">${code ? "Select baladiya" : "Select wilaya first"}</option>${communesOf(code).map((commune) => `<option value="${safe(commune)}">${safe(commune)}</option>`).join("")}`;
}
function adminHeaders() { return { "x-kdb-admin-token": state.admin.token }; }
async function refreshAdmin(notice = "") { state.admin = { token: state.admin.token, ...(await api("/api/admin/store", { headers: adminHeaders() })) }; state.notice = notice; render(); }
async function mutate(url, method, payload, notice) { await api(url, { method, headers: adminHeaders(), body: payload === undefined ? undefined : JSON.stringify(payload) }); await refreshAdmin(notice); }
function value(form, name) { return new FormData(form).get(name); }
function checked(form, name) { return new FormData(form).get(name) === "on"; }

function bind() {
  app.querySelectorAll("[data-action]").forEach((element) => element.addEventListener("click", async () => {
    const action = element.dataset.action;
    try {
      if (action === "bag") { state.bagOpen = true; state.order = null; render(); }
      if (action === "close-bag") { state.bagOpen = false; state.order = null; render(); }
      if (action === "language") { state.lang = state.lang === "en" ? "ar" : "en"; localStorage.setItem("kdb-hb-language", state.lang); render(); }
      if (action === "product") { state.productId = element.dataset.product; render(); }
      if (action === "close-product") { state.productId = null; render(); }
      if (action === "add") addProduct(element.dataset.product, element.dataset.variant);
      if (action === "filter") { state.filter = element.dataset.filter; state.collection = "all"; render(); }
      if (action === "collection") { state.collection = element.dataset.collection; state.filter = "all"; document.querySelector("#shop")?.scrollIntoView({ behavior: "smooth" }); render(); }
      if (action === "quantity") { const [productId, variantId] = element.dataset.key.split(":"); const line = state.cart.find((item) => item.productId === productId && item.variantId === variantId); if (line) { const variant = getVariant(getProduct(productId), variantId); const permittedQuantity = Math.min(8, variant.stock === undefined ? 8 : variant.stock); line.quantity = Math.min(Math.max(0, line.quantity + Number(element.dataset.delta)), permittedQuantity); if (line.quantity === 0) state.cart = state.cart.filter((item) => item !== line); persistCart(); render(); } }
      if (action === "hero-next") { state.heroIndex = (state.heroIndex + 1) % state.store.content.heroSlides.length; render(); }
      if (action === "hero-prev") { state.heroIndex = (state.heroIndex - 1 + state.store.content.heroSlides.length) % state.store.content.heroSlides.length; render(); }
      if (action === "hero-dot") { state.heroIndex = Number(element.dataset.index); render(); }
      if (action === "admin-nav") { state.adminSection = element.dataset.section; state.notice = ""; state.editor = null; render(); }
      if (action === "admin-logout") { state.admin = null; state.notice = ""; state.editor = null; render(); }
      if (action === "new-product") { state.editor = { kind: "product", record: { id: "", name: "", categoryId: state.admin.categories[0]?.id || "textile", sku: "", price: 0, stock: 0, status: "draft", image: state.admin.media[0]?.url || "", gallery: [], variants: [], colors: [], attributes: [], collectionIds: [], tags: [], offer: {} } }; render(); }
      if (action === "edit-product") { state.editor = { kind: "product", record: state.admin.products.find((item) => item.id === element.dataset.product) }; render(); }
      if (action === "close-editor") { state.editor = null; render(); }
      if (action === "new-category") { state.editor = { kind: "category", record: { id: "", name: "", image: state.admin.media[0]?.url || "", visible: true } }; render(); }
      if (action === "edit-category") { state.editor = { kind: "category", record: state.admin.categories.find((item) => item.id === element.dataset.id) }; render(); }
      if (action === "new-collection") { state.editor = { kind: "collection", record: { id: "", name: "", image: state.admin.media[0]?.url || "", productIds: [], visible: true } }; render(); }
      if (action === "edit-collection") { state.editor = { kind: "collection", record: state.admin.collections.find((item) => item.id === element.dataset.id) }; render(); }
      if (action === "new-hero") { state.editor = { kind: "hero", record: { id: "", title: "", image: state.admin.media[0]?.url || state.admin.products[0]?.image || "", enabled: true, sortOrder: state.admin.content.heroSlides.length } }; render(); }
      if (action === "edit-hero") { state.editor = { kind: "hero", record: state.admin.content.heroSlides.find((item) => item.id === element.dataset.id) }; render(); }
      if (action === "delete") { if (window.confirm("Remove this record from KDB?")) await mutate(`/api/admin/${element.dataset.kind}/${encodeURIComponent(element.dataset.id)}`, "DELETE", undefined, "Record removed."); }
      if (action === "delete-hero") { if (window.confirm("Remove this hero slide?")) await mutate(`/api/admin/heroes/${encodeURIComponent(element.dataset.id)}`, "DELETE", undefined, "Hero slide removed."); }
      if (action === "delivery-reset") { if (window.confirm("Reset all 58 delivery rules to baseline?")) await mutate("/api/admin/delivery/reset", "POST", {}, "Delivery matrix reset to baseline."); }
      if (action === "backup") { const data = await api("/api/admin/backup", { headers: adminHeaders() }); const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const href = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = href; link.download = `kdb-backup-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(href); state.notice = "KDB backup downloaded."; render(); }
      if (action === "restore") { const file = document.querySelector("#restore-file")?.files?.[0]; if (!file) throw new Error("Select a JSON backup first."); if (!window.confirm("Restore this backup and replace the local repository?")) return; const data = JSON.parse(await file.text()); await mutate("/api/admin/restore", "PUT", { store: data.store || data }, "Backup restored and normalized."); }
    } catch (error) { state.notice = error.message; render(); }
  }));

  app.querySelectorAll("[data-input]").forEach((input) => input.addEventListener(input.tagName === "SELECT" ? "change" : "input", () => {
    if (input.dataset.input === "search") state.query = input.value;
    if (input.dataset.input === "order-search") state.adminSearch = input.value;
    if (input.dataset.input === "order-status-filter") state.adminStatus = input.value;
    if (input.dataset.input === "media-search") state.mediaSearch = input.value;
    if (input.dataset.input === "media-usage-filter") state.mediaUsage = input.value;
    render();
  }));

  const detail = document.querySelector("#product-detail-form"); if (detail) detail.addEventListener("submit", (event) => { event.preventDefault(); addProduct(state.productId, value(detail, "variantId")); });
  const orderForm = document.querySelector("#order-form"); if (orderForm) { orderForm.addEventListener("change", (event) => { if (["wilayaCode", "deliveryType"].includes(event.target.name)) updateBaladiya(); }); orderForm.addEventListener("submit", async (event) => { event.preventDefault(); const error = document.querySelector("#form-error"); try { const data = await api("/api/orders", { method: "POST", body: JSON.stringify({ fullName: value(orderForm, "fullName"), phone: value(orderForm, "phone"), wilayaCode: value(orderForm, "wilayaCode"), deliveryType: value(orderForm, "deliveryType"), baladiya: value(orderForm, "baladiya"), lines: state.cart, source: "storefront" }) }); state.cart = []; persistCart(); state.order = data.order; await loadPublic(); render(); } catch (reason) { error.textContent = reason.message; } }); updateBaladiya(); }
  const login = document.querySelector("#admin-login"); if (login) login.addEventListener("submit", async (event) => { event.preventDefault(); const error = document.querySelector("#admin-error"); const token = value(login, "token"); try { await api("/api/admin/session", { method: "POST", body: JSON.stringify({ token }) }); state.admin = { token, ...(await api("/api/admin/store", { headers: { "x-kdb-admin-token": token } })) }; render(); } catch (reason) { error.textContent = reason.message; } });
  app.querySelectorAll("[data-order-form]").forEach((form) => form.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate(`/api/admin/orders/${encodeURIComponent(form.dataset.orderForm)}`, "PATCH", { status: value(form, "status"), notes: value(form, "notes") }, "COD order operation saved."); } catch (error) { state.notice = error.message; render(); } }));
  app.querySelectorAll("[data-delivery-form]").forEach((form) => form.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate(`/api/admin/delivery/${form.dataset.deliveryForm}`, "PATCH", { stopDeskFee: Number(value(form, "stopDeskFee")), domicileFee: Number(value(form, "domicileFee")), enabled: checked(form, "enabled"), free: checked(form, "free") }, `Wilaya ${form.dataset.deliveryForm} saved.`); } catch (error) { state.notice = error.message; render(); } }));
  const deliveryBulk = document.querySelector("#delivery-bulk"); if (deliveryBulk) deliveryBulk.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate("/api/admin/delivery/bulk", "PUT", { mode: value(deliveryBulk, "mode"), delta: Number(value(deliveryBulk, "delta")), enabledOnly: checked(deliveryBulk, "enabledOnly") }, "Delivery matrix updated."); } catch (error) { state.notice = error.message; render(); } });
  app.querySelectorAll("[data-product-form]").forEach((form) => form.addEventListener("submit", async (event) => { event.preventDefault(); try { const payload = { id: form.dataset.productForm === "new" ? undefined : form.dataset.productForm, name: value(form, "name"), nameAr: value(form, "nameAr"), categoryId: value(form, "categoryId"), sku: value(form, "sku"), material: value(form, "material"), price: Number(value(form, "price")), stock: Number(value(form, "stock")), status: value(form, "status"), position: Number(value(form, "position")), image: value(form, "image"), hoverImage: value(form, "hoverImage"), description: value(form, "description"), descriptionAr: value(form, "descriptionAr"), featured: checked(form, "featured"), visible: checked(form, "visible"), discoveryEnabled: checked(form, "discoveryEnabled"), customSizeEnabled: checked(form, "customSizeEnabled"), lifestyleEnabled: checked(form, "lifestyleEnabled"), gallery: parseJson(value(form, "gallery"), "Gallery"), variants: parseJson(value(form, "variants"), "Variants"), colors: parseJson(value(form, "colors"), "Colours"), attributes: parseJson(value(form, "attributes"), "Attributes"), collectionIds: parseJson(value(form, "collectionIds"), "Collections"), tags: parseJson(value(form, "tags"), "Tags"), publishAt: value(form, "publishAt") || null, unpublishAt: value(form, "unpublishAt") || null, offer: { enabled: checked(form, "offerEnabled"), label: value(form, "offerLabel"), endsAt: null } }; await mutate("/api/admin/products", "PUT", payload, "Material study saved."); state.editor = null; } catch (error) { state.notice = error.message; render(); } }));
  app.querySelectorAll("[data-record-form]").forEach((form) => form.addEventListener("submit", async (event) => { event.preventDefault(); try { const kind = form.dataset.recordForm; const payload = { id: form.dataset.recordId === "new" ? undefined : form.dataset.recordId, name: value(form, "name"), nameAr: value(form, "nameAr"), description: value(form, "description"), descriptionAr: value(form, "descriptionAr"), image: value(form, "image"), position: Number(value(form, "position")), visible: checked(form, "visible"), parentId: value(form, "parentId"), navigation: checked(form, "navigation"), colorFilterVisible: checked(form, "colorFilterVisible"), productIds: kind === "collections" ? parseJson(value(form, "productIds"), "Product IDs") : undefined }; await mutate(`/api/admin/${kind}`, "PUT", payload, `${kind.slice(0, -1)} saved.`); state.editor = null; } catch (error) { state.notice = error.message; render(); } }));
  app.querySelectorAll("[data-hero-form]").forEach((form) => form.addEventListener("submit", async (event) => { event.preventDefault(); try { const payload = { id: form.dataset.heroForm === "new" ? undefined : form.dataset.heroForm, kicker: value(form, "kicker"), kickerAr: value(form, "kickerAr"), name: value(form, "name"), nameAr: value(form, "nameAr"), description: value(form, "description"), descriptionAr: value(form, "descriptionAr"), action: value(form, "action"), actionAr: value(form, "actionAr"), href: value(form, "href"), externalUrl: value(form, "externalUrl"), textTone: value(form, "textTone"), position: Number(value(form, "position")), image: value(form, "image"), mobileImage: value(form, "mobileImage") || undefined, fallbackImage: value(form, "fallbackImage") || undefined, enabled: checked(form, "enabled") }; await mutate("/api/admin/heroes", "PUT", payload, "Hero slide saved."); state.editor = null; } catch (error) { state.notice = error.message; render(); } }));
  const contentForm = document.querySelector("#content-form"); if (contentForm) contentForm.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate("/api/admin/content", "PUT", { about: { title: value(contentForm, "aboutTitle"), body: value(contentForm, "aboutBody"), titleAr: value(contentForm, "aboutTitleAr"), bodyAr: value(contentForm, "aboutBodyAr") }, projects: parseJson(value(contentForm, "projects"), "Projects"), statistics: parseJson(value(contentForm, "statistics"), "Statistics"), certifications: parseJson(value(contentForm, "certifications"), "Certifications"), sectionVisibility: parseJson(value(contentForm, "sectionVisibility"), "Section visibility") }, "Public content saved."); } catch (error) { state.notice = error.message; render(); } });
  const mediaForm = document.querySelector("#media-form"); if (mediaForm) mediaForm.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate("/api/admin/media", "PUT", { name: value(mediaForm, "name"), url: value(mediaForm, "url"), usage: value(mediaForm, "usage"), section: value(mediaForm, "section"), provider: value(mediaForm, "provider"), tags: value(mediaForm, "tags").split(",").map((item) => item.trim()).filter(Boolean) }, "Media asset added."); } catch (error) { state.notice = error.message; render(); } });
  const settingsForm = document.querySelector("#settings-form"); if (settingsForm) settingsForm.addEventListener("submit", async (event) => { event.preventDefault(); try { const identity = { ...parseJson(value(settingsForm, "identityJson"), "Identity"), storeName: value(settingsForm, "storeName"), contactPhone: value(settingsForm, "contactPhone"), email: value(settingsForm, "email"), whatsappUrl: value(settingsForm, "whatsappUrl"), privacyUrl: value(settingsForm, "privacyUrl"), termsUrl: value(settingsForm, "termsUrl") }; const presentation = { ...parseJson(value(settingsForm, "presentationJson"), "Presentation"), heroInterval: Number(value(settingsForm, "heroInterval")) }; const catalog = parseJson(value(settingsForm, "catalogJson"), "Catalogue experience"); const marketing = parseJson(value(settingsForm, "marketingJson"), "Marketing configuration"); const seo = parseJson(value(settingsForm, "seoJson"), "SEO configuration"); await mutate("/api/admin/settings", "PUT", { announcement: value(settingsForm, "announcement"), storeOpen: checked(settingsForm, "storeOpen"), identity, presentation, catalog, delivery: { freeDeliveryThreshold: Number(value(settingsForm, "freeDeliveryThreshold")), handlingDays: value(settingsForm, "handlingDays"), fulfilmentMessage: value(settingsForm, "fulfilmentMessage") }, marketing, seo }, "Store settings saved."); } catch (error) { state.notice = error.message; render(); } });
  const teamForm = document.querySelector("#team-form"); if (teamForm) teamForm.addEventListener("submit", async (event) => { event.preventDefault(); try { await mutate("/api/admin/team", "PUT", { name: value(teamForm, "name"), role: value(teamForm, "role"), phone: value(teamForm, "phone"), active: checked(teamForm, "active") }, "Team directory entry added."); } catch (error) { state.notice = error.message; render(); } });
}

async function loadPublic() { state.store = await api("/api/store"); }
let heroTimer;
function startHeroTimer() {
  clearInterval(heroTimer);
  const interval = Number(publicSetting("presentation.heroInterval", 6000));
  if (publicSetting("presentation.heroAutoplay", true) && (state.store.content.heroSlides?.length || 0) > 1) heroTimer = setInterval(() => { if (!state.bagOpen && !state.productId && location.hash !== "#admin") { state.heroIndex = (state.heroIndex + 1) % state.store.content.heroSlides.length; render(); } }, Math.max(2000, interval));
}
window.addEventListener("hashchange", () => { state.productId = null; render(); });
async function boot() { try { await loadPublic(); render(); startHeroTimer(); } catch (error) { app.innerHTML = `<main class="fatal"><h1>KDB is resting.</h1><p>${safe(error.message)}</p></main>`; } }
boot();
